def right_edge_view(tree):
    view = []
    stack = [(tree, 0)]
    while stack:
        node, depth = stack.pop()
        if node is None:
            continue
        if depth == len(view):
            view.append(node[0])
        stack.append((node[2], depth + 1))
        stack.append((node[1], depth + 1))
    return view
